63:         public void DoWork()
64:         {
65:             // 启动之前先把动作排好
66:             this.S1ActionNodeController.Init();
67: 
68:             // 总循环
69:             while (Signal.WaitStart())
70:             {
71:                 // 移动到安全位置
72:                 this.DispenseController.MoveToSafePos();
73: 
74:                 DispenseRunTimeProvider.RecordTime("点胶区等流道来料信号......", $"点胶线程等待来料信号");
75: 
76:                 if (MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.OffLineWork)
77:                 {
78:                     // 等待流道信号             
79:                     if (!this.GetInputSignal())
80:                     {
81:                         DispenseRunTimeProvider.RecordTime("点胶区等流道来料信号......", $"点胶线程未收到信号，回到安全位置");
82: 
83:                         // 点胶Z轴移动到安全位置
84:                         this.DispenseController.MoveToSafePos();
85:                         return;
86:                     }
87:                 }
88: 
89:                 DispenseRunTimeProvider.RecordTime("点胶区等流道来料信号......", $"点胶线程收到信号，准备开始工作");
90: 
91:                 DispenseRunTimeProvider.IsFirstDispense = true;
92: 
93:                 if (this.Enable)
94:                 {
95:                     if (!TransportProgram.GetInstance().DispenseSubSectionProgram.TransportUnit.TransportUnitInfo.IsProduct)
96:                     {
97:                         TransportProgram.GetInstance().DispenseSubSectionProgram.TransportUnit =
98:                             new TransportUnit(CurrentMachineSystemEnum.System1);
99:                         TransportProgram.GetInstance().DispenseSubSectionProgram.TransportUnit.TransportUnitInfo.IsProduct =
100:                             true;
101: 
102:                         DispenseRunTimeProvider.RecordTime("点胶区等流道来料信号......", $"点胶重置产品对象成功");
103:                     }
104:  
105:                     // 注入制程
106:                     this.S1ActionNodeController.InjectSteps(
107:                         TransportProgram.GetInstance().DispenseSubSectionProgram.TransportUnit);
108: 
109:                     DispenseRunTimeProvider.RecordTime("点胶区等流道来料信号......", $"点胶注入产品对象信息");
110: 
111:                     // 开始生产
112:                     StatisticsDomain.GetInstance().CalculateDispenseCycle();
113: 
114:                     DispenseRunTimeProvider.RecordTime("点胶区等流道来料信号......", $"开始动作循环");
115: 
116:                     // 不分段，中间和流道交互的过程封装成动作，到时候直接注入到动作中
117:                     while (Signal.WaitStart())
118:                     {
119:                         ActionNode actionNode = this.S1ActionNodeController.GetNextActionNode();
120: 
121:                         // 没有actionNode了，代表全部都已经做完了，直接退出
122:                         if (actionNode == null)
123:                         {
124:                             break;
125:                         }
126: 
127:                         if (!actionNode.IsDoWork())
128:                         {
129:                             goto Finish;
130:                         }
131: 
132:                         // 如果这个动作不是测高动作则收回点胶气缸
133:                         if (actionNode.Name != "S1DispenseMeasureActionNode" 
134:                             && actionNode.Name != "S1CarrierMeasureHeightActionNode"
135:                             && actionNode.Name != "S1SubstrateMeasureHeightActionNode"
136:                             && actionNode.Name != "S1ModuleMeasureHeightActionNode")
137:                         {
138:                             if (MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.OffLineWork)
139:                             {
140:                                 // 收回点胶气缸
141:                                 System1Domain.GetInstance().DispenseMeasureHeightController
142:                                     .CloseDispenseHeightMeasurementCylinder();
143:                             }
144: 
145:                             DispenseRunTimeProvider.RecordTime("系统1", "收回点胶气缸完成");
146:                         }
147: 
148:                         // 执行动作的主要方法都在这个里面
149:                         ExcuteResult ret = actionNode.DoWork();
150: 
151:                         if (ret == ExcuteResult.Retry)
152:                         {
153:                             continue;
154:                         }
155:                         else if (ret != ExcuteResult.Success)
156:                         {
157:                             // 如果当前动作没有成功，直接退出线程
158:                             this.DispenseController.MoveToSafePos();
159:                             Machine.GetInstance().Stop();
160:                             DispenseRunTimeProvider.RecordTime("点胶工作线程", $"点胶线程,动作：{actionNode.Name}执行未成功，线程结束");
161:                             return;
162:                         }
163: 
164:                         Finish:
165:                         this.S1ActionNodeController.FinishCurrentActionNode();
166:                     }
167:                 }
168: 
169:                 this.DispenseController.MoveToSafePos();
170: 
171:                 // 如果循环因为停止而退出的，就不要给流道发送可以传料的信号了
172:                 if (Machine.GetInstance().IsStop() == false)
173:                 {
174:                     // 点胶执行完成，告诉流道移走产品，等待产品流走
175:                     SignalPool.GetInstance().AllowDispenseTransferToBondSignal.Set();
176:                 }
177: 
178:                 DispenseRunTimeProvider.RecordTime("点胶工作完成", $"点胶工作完成，告诉轨道可以传输产品");
179: 
180:                 // 全部完成后重置产品状态
181:                 this.S1ActionNodeController.Finish();
182:             }

63:                     // 修改当前焊点的状态为点胶完成
64:                     bondPosition.S1FinishedStep(this.ActionNodeController.SingleProcessStepName);
65:                 }
66: 
67:                 // 单步工作
68:                 if (!System1Domain.GetInstance().WaitSingleStep())
69:                 {
70:                     return ExcuteResult.Abort;
71:                 }
72: 
73:                 #endregion
74: 
75:                 // 执行预点胶
76:                 if (System1Domain.GetInstance().DispenseActionNodes.PreDispenseAction.DoWork() != ExcuteResult.Success)
77:                 {
78:                     return ExcuteResult.Alarm;
79:                 }
80: 
81:                 // 如果在预点胶的时候点了停止则退出
82:                 if (!Signal.WaitStart())
83:                 {
84:                     return ExcuteResult.Fail;
85:                 }

144:                 if (System1Program.GetInstance().DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.BeforeEveryDispense)
145:                 {
146:                     DispenseRunTimeProvider.RecordTime("系统1点胶动作执行", $"预点胶标志 - 第一次点胶 置为true");
147:                     DispenseRunTimeProvider.IsFirstDispense = true;
148:                 }
149:                 else 
150:                 {
151:                     DispenseRunTimeProvider.RecordTime("系统1点胶动作执行", $"预点胶标志 - 第一次点胶 置为false");
152:                     DispenseRunTimeProvider.IsFirstDispense = false;
153:                 }
154: 
155:                 DispenseRunTimeProvider.RecordTime("点胶结束", "点胶结束 ----------------");
156: 
157:                 return ExcuteResult.Success;

177:         private bool IsDispense()
178:         {
179:             if (this.IsManual)
180:             {
181:                 // 手动模式直接执行预点胶，并记录时间
182:                 DispenseRunTimeProvider.RecordTime("预点胶", $"预点胶手动开始");
183:                 return true;
184:             }
185:             else if (System1Program.GetInstance().DispenserProgram.Dispenser.PreDispense.PreDispensingMode == PreDispensingModeEnum.Off
186:                 && System1Program.GetInstance().DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.Off)
187:             {
188:                 // 预点胶模式和时机都为Off，不执行预点胶
189:                 return false;
190:             }
191:             else if (DispenseRunTimeProvider.IsFirstDispense
192:                      && System1Domain.GetInstance().ActionNodeController.CurrentActionNode is S1DispenseActionNode
193:                      && System1Program.GetInstance().DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.BeforeComingFirstDispense
194:                      )
195:             {
196:                 // 预点胶时机为入料后第一次点胶前，并且是第一次点胶，执行预点胶，并记录时间
197:                 DispenseRunTimeProvider.RecordTime("预点胶", $"预点胶条件通关 - 入料后第一次点胶前");
198:                 return true;
199:             }
200:             else if ((DateTime.Now - this.LastDispenseTime).TotalMilliseconds
201:                      > System1Domain.GetInstance().System1Program.DispenserProgram.Dispenser.PreDispense.PreDispensingTimeInterval
202:                      && System1Program.GetInstance().DispenserProgram.Dispenser.PreDispense.PreDispensingMode == PreDispensingModeEnum.Periodic)
203:             {
204:                 // 预点胶模式为周期性，并且距离上次点胶时间超过预设的时间间隔，执行预点胶，并记录时间
205:                 DispenseRunTimeProvider.RecordTime("预点胶", $"预点胶条件通关 - 预点胶时间条件满足");
206:                 return true;
207:             }
208: 
209:             return false;
210:         }

74:         public override ExcuteResult DoWork()
75:         {
76:             this.WorkStart?.Invoke();
77:             this.State = RunStateEnum.Running;
78:             try
79:             {
80:                 // 判断是否需要执行预点胶动作
81:                 if (!this.IsDispense())
82:                 {
83:                     return ExcuteResult.Success;
84:                 }
85: 
86:                 // 判断预点胶的必要条件
87:                 if (this.IsAlarm())
88:                 {
89:                     return ExcuteResult.Abort;
90:                 }
91: 
92:                 // 挤胶
93:                 this.EpoxySqueeze();
94:                 
95:                 DispenseRunTimeProvider.RecordTime("预点胶", $"预点胶开始----------------");
96: 
97:                 // 获取点胶位置的集合
98:                 List<AKRSPoint3D> lists = this.PreDispensePlateProgram
99:                     .GetEpoxy(this.DispenserProgram.Dispenser.PreDispense.RepeatPreDispensing);
100: 
101:                 if (lists == null || lists.Count == 0)
102:                 {
103:                     throw new Exception("预点胶位置获取失败，请检测程式是否存在问题");
104:                 }
105: 
106:                 // 获取预点胶的图案
107:                 EpoxyApplication epoxyApplication = (EpoxyApplication)EpoxyApplicationRepository.GetInstance()
108:                     .Find(this.DispenserProgram.Dispenser.PreDispense.EpoxyApplicationName);
109: 
110:                 DispenseRunTimeProvider.RecordTime("预点胶", $"获取预点胶图案：{this.DispenserProgram.Dispenser.PreDispense.EpoxyApplicationName}完成");
111: 
112:                 foreach (AKRSPoint3D point in lists)
113:                 {
114:                     // 空跑模式不出胶
115:                     bool isDrip = MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle;
116: 
117:                     // 开始点胶动作
118:                     if (System1Domain.GetInstance().DispenseController.InterpolationApplication(epoxyApplication, point, isDrip, true, 0) != ExcuteResult.Success)
119:                     {
120:                         return ExcuteResult.Alarm;
121:                     }
122:                 }
123: 
124:                 DispenseRunTimeProvider.RecordTime("预点胶", $"预点胶结束----------------");
125: 
126:                 // 获取胶后检测对象
127:                 PostBondInspection postBondInspection = (PostBondInspection)PostBondInspectionRepository.GetInstance()
128:                     .Find(this.DispenserProgram.Dispenser.PreDispense.PreDispenseCheckName);
129: 
130:                 DispenseRunTimeProvider.RecordTime("预点胶", $"获取胶后检测对象：{this.DispenserProgram.Dispenser.PreDispense.PreDispenseCheckName}完成");
131: 
132:                 if (postBondInspection != null)
133:                 {
134:                     this.CheckEpoxyApplication(postBondInspection, postBondInspection.VisionConfig.P1VisionPos + lists.Last());
135: 
136:                     DispenseRunTimeProvider.RecordTime("预点胶", $"胶后检测完成");
137:                 }
138:                 else if (this.IsManual)
139:                 {
140:                     System1Domain.GetInstance().DispenseController.MoveZToSafePos();
141: 
142:                     DispenseRunTimeProvider.RecordTime("预点胶", $"手动模式-Z轴移到安全高度完成");
143: 
144:                     AKRSPoint3D visionPos = System1Domain.GetInstance().DispenseController.GetG0VisionPos(lists[lists.Count - 1]);
145: 
146:                     visionPos.Z += epoxyApplication.PrePlantOffSetZ;
147: 
148:                     System1Domain.GetInstance().DispenseController.MoveToG0Pos3D(visionPos);
149: 
150:                     DispenseRunTimeProvider.RecordTime("预点胶", $"手动模式-去视觉位完成");
151:                 }
152: 
153:                 this.LastDispenseTime = DateTime.Now;
154:                 this.IsManual = false;
155:                 
156:                 return ExcuteResult.Success;
157:             }
158:             catch (Exception ex)
159:             {
160:                 LogHelper.Post(Level.Error, $"流程{this.Name}运行故障！", ex, LogCategory.Dispense);
161:                 AKRSMessageBoxExt.Show(ex.Message, "预点胶异常", new string[] { "异常" }, new DialogResult[] { DialogResult.Yes });
162:                 return ExcuteResult.Exception;
163:             }
164:             finally
165:             {
166:                 this.IsManual = false;
167:                 this.State = RunStateEnum.Stop;
168:                 WorkStop?.Invoke();
169:             }
170:         }

177:         private bool IsDispense()
178:         {
179:             if (this.IsManual)
180:             {
181:                 // 手动模式直接执行预点胶，并记录时间
182:                 DispenseRunTimeProvider.RecordTime("预点胶", $"预点胶手动开始");
183:                 return true;
