55:         public void InitPre()
56:         {
57:             this.EpoxyArea = new AKRSPoint3D[this.PreDispensePlatePara.Rows, this.PreDispensePlatePara.Columns];
58: 
59:             double columnSpacing = 0;
60: 
61:             double rowSpacing = 0;
62: 
63:             if (this.PreDispensePlatePara.Columns > 1)
64:             {
65:                 // 计算行列间距
66:                 columnSpacing = (this.PreDispensePlatePara.PreDispensePlateEndPos.X
67:                                  - this.PreDispensePlatePara.PreDispensePlateStartPos.X)
68:                                 / (this.PreDispensePlatePara.Columns - 1);
69:             }
70: 
71:             if (this.PreDispensePlatePara.Rows > 1)
72:             {
73:                 // 计算行列间距
74:                 rowSpacing = (this.PreDispensePlatePara.PreDispensePlateEndPos.Y
75:                               - this.PreDispensePlatePara.PreDispensePlateStartPos.Y)
76:                              / (this.PreDispensePlatePara.Rows - 1);
77:             }
78: 
79:             for (int i = 0; i < this.PreDispensePlatePara.Rows; i++)
80:             {
81:                 for (int j = 0; j < this.PreDispensePlatePara.Columns; j++)
82:                 {
83:                     this.EpoxyArea[i, j] = new AKRSPoint3D(
84:                         this.PreDispensePlatePara.PreDispensePlateStartPos.X + j * columnSpacing,
85:                         this.PreDispensePlatePara.PreDispensePlateStartPos.Y + i * rowSpacing,
86:                         this.PreDispensePlatePara.PreDispensePlateStartPos.Z);
87:                 }
88:             }
89: 
90:             this.Index = 0;
91:             System1Domain.GetInstance().System1Program.Save();
92:         }
93: 
94:         /// <summary>
95:         /// 获取画胶的点位，此点位为G0中的坐标
96:         /// </summary>
97:         /// <returns>需要画胶的点位</returns>
98:         public AKRSPoint3D GetEpoxy()
99:         {
100:             if (this.EpoxyArea == null || this.EpoxyArea.Length == 0)
101:             {
102:                 this.InitPre();
103:             }
104: 
105:             if (this.Index == this.EpoxyArea.Length)
106:             {
107:                 if (MachineStateModel.GetInstance().IsDryCycle)
108:                 {
109:                     this.InitPre();
110:                 }
111:                 else
112:                 {
113:                     DialogResult dialogResult = AKRSMessageBoxExt.Show(
114:                        $"预点胶板位置已经使用完，请清洁预点胶板 \r\n",
115:                        "预点胶板未清洁报警",
116:                        new string[] { "确认", "停止" },
117:                        new DialogResult[] { DialogResult.OK, DialogResult.Abort },
118:                        AlarmLevel.SecondLevel);
119: 
120:                     if (dialogResult == DialogResult.OK)
121:                     {
122:                         this.InitPre();
123:                     }
124:                     else
125:                     {
126:                         throw new Exception("预点胶板已满，无法继续工作");
127:                     }
128:                 }
129:             }
130: 
131:             // 这个是判断外界行列数有没有改变
132:             if (this.PreDispensePlatePara.Rows != this.EpoxyArea.GetLength(0)
133:                 || this.PreDispensePlatePara.Columns != this.EpoxyArea.GetLength(1))
134:             {
135:                 DialogResult dialogResult = AKRSMessageBoxExt.Show(
136:                     $" 预点胶板行列数发生改变，请清洁预点胶板 \r\n",
137:                     " 预点胶板行列数发生改变报警",
138:                     new string[] { "确认", "停止" },
139:                     new DialogResult[] { DialogResult.OK, DialogResult.Abort },
140:                     AlarmLevel.SecondLevel);
141: 
142:                 if (dialogResult == DialogResult.OK)
143:                 {
144:                     this.InitPre();
145:                 }
146:                 else
147:                 {
148:                     throw new Exception("预点胶板已更改，无法继续工作");
149:                 }
150:             }
151: 
152:             int column = 0;
153:             int row = 0;
154: 
155:             if (this.PreDispensePlatePara.Rows != 0 && this.PreDispensePlatePara.Columns != 0)
156:             {
157:                 column = this.Index / this.PreDispensePlatePara.Rows;
158:                 row = this.Index - column * this.PreDispensePlatePara.Rows;
159:             }
160: 
161:             this.Index++;
162: 
163:             AKRSPoint3D point3D = this.EpoxyArea[row, column];
164: 
165:             System1Domain.GetInstance().System1Program.Save();
166: 
167:             return point3D;
168:         }
