171:         /// <summary>
172:         /// 获取画胶的点位，此点位为G0中的坐标
173:         /// </summary>
174:         /// <param name="count">个数</param>
175:         /// <returns>画胶点位的集合</returns>
176:         public List<AKRSPoint3D> GetEpoxy(int count)
177:         {
178:             List<AKRSPoint3D> points = new List<AKRSPoint3D>();
179: 
180:             for (int i = 0; i < count; i++)
181:             {
182:                 AKRSPoint3D point3D = this.GetEpoxy();
183: 
184:                 if (point3D == null)
185:                 {
186:                     return null;
187:                 }
188: 
189:                 points.Add(point3D);
190:             }
191: 
192:             return points;
193:         }

