361:         public ExcuteResult PostBondEpoxyCheck(List<BaseAlgResult> baseAlgResults,BondPosition bondPosition,PRHardware pRHardware)
362:         {
363:             List<double> avgX = new List<double>();
364:             List<double> avgY = new List<double>();
365:             List<double> avgArea = new List<double>();
366: 
367:             string alarmMessage = string.Empty;
368: 
369:             if (baseAlgResults == null)
370:             {
371:                 alarmMessage = this.Name + "：胶量检测未找到识别点";
372:                 return this.PostBondCheckHand(this.VisionConfig.P1PRName, alarmMessage, pRHardware);
373:             }
374:             else if (baseAlgResults.Count != (int)this.PostBondEpoxyNum)
375:             {
376:                 alarmMessage = this.Name + "：胶量检测识别到的个数不对";
377:                 return this.PostBondCheckHand(this.VisionConfig.P1PRName, alarmMessage, pRHardware);
378:             }
379:             else
380:             {
381:                 for (int i = 0; i < baseAlgResults.Count; i++)
382:                 {
383:                     BlobResult blobResult = (BlobResult)baseAlgResults[i];
384:                     MatchResult matchResult = new MatchResult(blobResult.CenterX, blobResult.CenterY, blobResult.Area);
385: 
386:                     // 定位结果和示教位置之间的差值
387:                     AKRSPoint3D pointResult = System2Module.GetInstance().BondModule.BondCameraCoordinateSystem
388:                         .ForwardConvertCoordinate(new AKRSPoint3D(matchResult.CenterX, matchResult.CenterY, 0));
389: 
390:                     double offsetX = pointResult.X - this.PostBondEpoxyCenterX[i] - this.PostBondDistanceX;
391: 
392:                     double offsetY = pointResult.Y - this.PostBondEpoxyCenterY[i] - -this.PostBondDistanceY;
393: 
394:                     // 计算圆形面积
395:                     double cameraRatio = System2Domain.GetInstance().BondModuleController.GetCameraRatio();
396: 
397:                     double newArea = Math.Round(blobResult.Area * cameraRatio * cameraRatio, 4);
398:                     double oldArea = Math.Round(this.PostBondEpoxyArea[i] * cameraRatio * cameraRatio, 4);
399: 
400:                     double limitArea = 0;
401: 
402:                     if (!this.IsCircle)
403:                     {
404:                         // 面积判断
405:                         limitArea = Math.Round(newArea / oldArea, 2);
406:                         if (limitArea > this.TolerantEpoxyMax
407:                             || limitArea < this.TolerantEpoxyMin)
408:                         {
409:                             alarmMessage +=
410:                                 $"胶量检测点 {i + 1} 的面积的检测最大比例为{this.TolerantEpoxyMax},"
411:                                 + $"最小比例为{this.TolerantEpoxyMin},当前值为{limitArea}\r\n"
412:                                 + $"当前面积为{newArea}mm²，标准面积为{oldArea}mm²";
413:                             break;
414:                         }
415:                     }
416:                     else
417:                     {
418:                         double newRadius = Math.Round(Math.Sqrt(newArea / Math.PI), 4);
419:                         double oldRadius = Math.Round(Math.Sqrt(oldArea / Math.PI), 4);
420: 
421:                         limitArea = Math.Round(newArea / oldArea, 2);
422: 
423:                         if (limitArea > this.TolerantEpoxyMax
424:                             || limitArea < this.TolerantEpoxyMin)
425:                         {
426:                             alarmMessage +=
427:                                $"胶量检测点 {i + 1} 半径的检测最大比例为{this.TolerantEpoxyMax},"
428:                                + $"最小比例为{this.TolerantEpoxyMin},当前值为{limitArea}\r\n"
429:                                + $"当前半径为{newRadius}mm²，标准半径为{oldRadius}mm²";
430:                             break;
431:                         }
432:                     }
433: 
434:                     avgX.Add(offsetX);
435:                     avgY.Add(offsetY);
436:                     avgArea.Add(limitArea);
437: 
438:                     // X方向判断
439:                     if (Math.Abs(offsetX) > this.LimitX)
440:                     {
441:                         alarmMessage =
442:                             $"胶量检测点 {i + 1} 的X方向的检测阈值为{this.LimitX}\r\n,当前值为{offsetX}\r\n";
443:                         break;
444:                     }
445: 
