129:         public void MoveToG0Pos3D(AKRSPoint3D point3D, bool isMeasureOpen = false)
130:         {
131:             DispenseRunTimeProvider.RecordTime("系统动作", $"移动到{point3D}");
132: 
133:             // 机械坐标
134:             AKRSPoint3D targetPos = this.DispenseCoordinateSystem.G0PosToSelf(point3D);
135: 
136:             DispenseRunTimeProvider.RecordTime("系统动作", $"移动到机械坐标{targetPos}");
137: 
138:             // 安全高度
139:             double safeHeight = this.DevicePara.DispenseModulePara.SafePoint3D.Z;
140:             DispenseRunTimeProvider.RecordTime("系统动作", $"绝对安全高度{safeHeight}");
141: 
142: 
143:             // 获取当前点胶平台上的TU
144:             TransportUnit transportUnit = TransportDomain.GetInstance().TransportProgram.DispenseSubSectionProgram.TransportUnit;
145: 
146:             // 如果TU上没有产品或者在自动运行的时候，先移动到Z轴的安全高度，移动XY，再移动Z轴
147:             if (Machine.GetInstance().IsWorking() == false
148:                 || transportUnit == null)
149:             {
150:                 // 如果当前位置和目标位置都比安全位置低，Z轴移动到安全位置，移动XY，最后移动Z轴
151:                 this.DispenseModule.AxisZAbsoluteMove(safeHeight);
152:                 this.DispenseModule.AxisXYAbsoluteMove(targetPos.X, targetPos.Y);
153:                 this.DispenseModule.AxisZAbsoluteMove(targetPos.Z);
154: 
155:                 DispenseRunTimeProvider.RecordTime("系统动作", $"先移动到安全高度{safeHeight}，XY移动到{targetPos.X},{targetPos.Y}，Z移动到{targetPos.Z}");
156:             }
157:             else if (isMeasureOpen && !MachineHardwareConfiguration.GetInstance().IsSystem1ConfigLaserMh)
158:             {
159:                 // 先移动到跨越的高度,移动XY，最后下降
160:                 this.DispenseModule.AxisZAbsoluteMove(targetPos.Z + this.DevicePara.DispenseModulePara.MeasureHeightCrossingHeights, false);
161:                 this.DispenseModule.AxisXYAbsoluteMove(targetPos.X, targetPos.Y, false);
162:                 this.DispenseModule.AxisZAbsoluteMove(targetPos.Z, false);
163:                 DispenseRunTimeProvider.RecordTime("系统动作", $"先移动到跨越的高度{targetPos.Z + this.DevicePara.DispenseModulePara.MeasureHeightCrossingHeights}，XY移动到{targetPos.X},{targetPos.Y}，Z移动到{targetPos.Z}");
164:             }
165:             else
166:             {
167:                 // 安全高度 = TU在GO中的位置 + TU设置的安全高度
168:                 safeHeight = transportUnit.CoordinateSystem.SelfPosToG0(new AKRSPoint3D()).Z
169:                              + ProductConfiguration.GetInstance().TransportUnitConfig
170:                                  .SafeHeight;
171: 
172:                 // 当前安全高度是测高针的安全高度，需要转换到点胶头上面
173:                 safeHeight = this.GetG0DispensePos(new AKRSPoint3D(0, 0, safeHeight)).Z;
174: 
175:                 // 将安全位置转到轴坐标
176:                 safeHeight = this.DispenseCoordinateSystem.G0PosToSelf(new AKRSPoint3D(0, 0, safeHeight)).Z;
177: 
178:                 DispenseRunTimeProvider.RecordTime("系统动作", $"安全高度{safeHeight}");
179: 
180:                 // 移动到位置
181:                 this.MoveToMachinePoint(targetPos, safeHeight);
182: 
183:                 DispenseRunTimeProvider.RecordTime("系统动作", $"移动到{point3D}完成");
184:             }
185:         }
