208:         public void MoveToMachinePoint(AKRSPoint3D point3D, double safeHeight)
209:         {
210:             // 将G0的点位转换到轴坐标
211:             AKRSPoint3D targetPos = point3D;
212: 
213:             // 当前位置
214:             double curPos = this.GetAxisPos().Z;
215: 
216:             DispenseRunTimeProvider.RecordTime("系统动作", $"当前高度{curPos}，目标高度{targetPos.Z}，安全高度{safeHeight}");
217: 
218:             // 判断位置，如果当前位置高于安全高度且目标位置位置也高于安全高度,可以三轴直接移动
219:             if (curPos >= safeHeight && targetPos.Z >= safeHeight)
220:             {
221:                 this.DispenseModule.AxisXYZAbsoluteMove(targetPos);
222:                 DispenseRunTimeProvider.RecordTime("系统动作", $"三轴一起移动");
223:             }
224:             else if (curPos > safeHeight && targetPos.Z < safeHeight)
225:             {
226:                 // 当前位置比安全位置高，目标位置比安全位置低，先移动XY，再移动Z轴
227:                 this.DispenseModule.AxisXYAbsoluteMove(targetPos.X, targetPos.Y);
228: 
229:                 // XY移动到位之后移动Z轴
230:                 this.DispenseModule.AxisZAbsoluteMove(targetPos.Z);
231: 
232:                 DispenseRunTimeProvider.RecordTime("系统动作", $"移动XY，再移动Z");
233:             }
234:             else if (curPos < safeHeight && targetPos.Z > safeHeight)
235:             {
236:                 // 当前位置比安全位置低，目标位置比安全位置高，先移动XY，再移动Z轴
237:                 this.DispenseModule.AxisZAbsoluteMove(targetPos.Z);
238:                 this.DispenseModule.AxisXYAbsoluteMove(targetPos.X, targetPos.Y);
239: 
240:                 DispenseRunTimeProvider.RecordTime("系统动作", $"移动Z，再移动XY");
241:             }
242:             else if (curPos < safeHeight && targetPos.Z <= safeHeight)
243:             {
244:                 // 如果当前位置和目标位置都比安全位置低，Z轴移动到安全位置，移动XY，最后移动Z轴
245:                 this.DispenseModule.AxisZAbsoluteMove(safeHeight);
246:                 this.DispenseModule.AxisXYAbsoluteMove(targetPos.X, targetPos.Y);
247:                 this.DispenseModule.AxisZAbsoluteMove(targetPos.Z);
248:                 DispenseRunTimeProvider.RecordTime("系统动作", $"移动Z，再移动XY，再移动Z");
249:             }
250:             else
251:             {
252:                 DispenseRunTimeProvider.RecordTime("系统动作", $"意外情况");
253:                 throw new Exception("点胶移动异常，请联系管理员");
254:             }

