347:         public void Stop()
348:         {
349:             // 改变设备状态
350:             Machine.GetInstance().SetState(MachineStateEnum.Stop);
351: 
352:             // 清除弹窗
353:             AKRSMessageBoxExt.ClearMessageBox();
354: 
355:             // 状态改为停止
356:             this.SetStopStateAlarm();
357: 
358:             // 退出单步模式
359:             MachineStateModel.GetInstance().IsSingleStepWork = false;
360: 
361:             // 重置Bond需料信号
362:             SignalPool.GetInstance().IsBondNeedChipSignal.ReSet();
363: 
364:             // 关要料信号
365:             if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online)
366:             {
367:                 TransportDomain.GetInstance().TransportController.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(false);
368:             }
369: 
370:             // 关闭顶针真空 
371:             WaferSubController.GetInstance().EjectController.CloseEjectionTableVacuum();
372: 
373:             // 焊后重新计数
374:             foreach (PostBondInspection postBondInspection in BondProgram.GetInstance().PostBondProgram.PostBondInspections)
375:             {
376:                 postBondInspection.CurrentDefectNumber = 0;
377:             }
378:         }
