217:         /// <summary>
218:         /// 获取来料信号
219:         /// </summary>
220:         /// <returns>结果</returns>
221:         private bool GetInputSignal()
222:         {
223:             while (true)
224:             {
225:                 Thread.Sleep(10);
226: 
227: 
228:                 if (Machine.GetInstance().IsPause())
229:                 {
230:                     continue;
231:                 }
232: 
233:                 // 执行预点胶
234:                 ExcuteResult result = System1Domain.GetInstance().DispenseActionNodes.PreDispenseAction.DoWork();
235: 
236:                 if (result != ExcuteResult.Success)
237:                 {
238:                     return false;
239:                 }
240: 
241:                 if (Machine.GetInstance().IsStop())
242:                 {
243:                     return false;
244:                 }
245:                 else if (Machine.GetInstance().IsPause())
246:                 {
247:                     continue;
248:                 }
249:                 else if (SignalPool.GetInstance().TransferToDispense1FinishedSignal.State == SignalStateEnum.Set)
250:                 {
251:                     SignalPool.GetInstance().TransferToDispense1FinishedSignal.State = SignalStateEnum.ReSet;
252:                     return true;
253:                 }
254:                 else if (SignalPool.GetInstance().TransferToDispense1FinishedSignal.State == SignalStateEnum.ReSet)
255:                 {
256:                     continue;
257:                 }
258:                 else
259:                 {
260:                     throw new Exception("点胶入料载台来料信号异常");
261:                 }
262:             }
263:         }

