177:         public override bool IsDoWork()
178:         {
179:             // 焊点
180:             BondPosition bp = System1Domain.GetInstance().ActionNodeController.CurrentBondPosition;
181: 
182:             if (bp == null)
183:             {
184:                 throw new Exception("获取当前焊点失败！请检查当前焊点是否已经被删除或者工作步骤配置有问题。\r\n 请清空载具后重试");
185:             }
186: 
187:             // 判断当前工艺制程是否开启
188:             if (bp.MatterProductState == MatterProductState.Disable
189:                 || bp.MatterProductState == MatterProductState.EnableInSystem2)
190:             {
191:                 return false;
192:             }
193: 
194:             // 如果当前焊点已经点过胶则退出
195:             if (!bp.IsS1NeedStep(this.ActionNodeController.SingleProcessStepName))
196:             {
197:                 return false;
198:             }
199: 
200: 
201: 
202:             return true;
203:         }

